import re
from dataclasses import dataclass, field
from typing import Optional

# A release heading. The date is optional: "## [Unreleased]" has none.
HEADING = re.compile(
    r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$"
)

# A maintainer comment, possibly spanning lines. When it ends its line, the
# whitespace before it and after it goes too, so no trailing spaces are left.
COMMENT_AT_END = re.compile(r"[ \t]*<!--.*?-->[ \t]*(?=\r?\n|\Z)", re.DOTALL)
COMMENT = re.compile(r"<!--.*?-->", re.DOTALL)


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def strip_comments(text):
    text = COMMENT_AT_END.sub("", text)
    return COMMENT.sub("", text)


def parse_changelog(text):
    releases = []
    current = None
    # Comments go first so that a commented-out heading is not treated as a release.
    for line in strip_comments(text).splitlines():
        match = HEADING.match(line) if line.startswith("## ") else None
        if match:
            current = Release(match.group("version"), match.group("date"))
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def normalize_body(lines):
    """Blank out whitespace-only lines, collapse blank runs, and trim both ends."""
    out = []
    for line in lines:
        line = line.rstrip()
        if line == "" and (not out or out[-1] == ""):
            continue
        out.append(line)
    while out and out[-1] == "":
        out.pop()
    return "\n".join(out)


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            body = normalize_body(release.body)
            title = f"{release.version} ({release.date})" if release.date else "Unreleased"
            if not body:
                return f"# {title}\n"
            return f"# {title}\n\n{body}\n"
    raise LookupError(version)

